/// PinDirection is the normalized electrical direction of a pin. Readers map their native
/// spelling onto this and keep the raw string in attributes ("direction_raw") when it does
/// not map cleanly.
///
/// POWER is the generic power/ground pin, for readers that do not distinguish source from sink.
/// POWER_IN marks a rail consumed, e.g. a chip's VCC. POWER_OUT marks a rail sourced, e.g. a
/// regulator output or a KiCad PWR_FLAG. The connectivity rules need that finer split to tell a
/// power driver from a power sink. Treat POWER as "either" when classifying drivers.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum PinDirection {
    Unspecified = 0,
    Input = 1,
    Output = 2,
    Inout = 3,
    Passive = 4,
    Power = 5,
    NoConnect = 6,
    PowerIn = 7,
    PowerOut = 8,
    /// A tri-state output drives its net only while enabled, so a net it shares with another tri-state
    /// pin is a bus rather than a conflict. It answers "is this net driven" and is no hard driver.
    Tristate = 9,
    /// An open-collector (or open-drain) output can only pull its net low. So several on one net are a
    /// wire-OR rather than a conflict, and a wire-OR needs a pull-up.
    OpenCollector = 10,
    /// An open-emitter (or open-source) output can only pull its net high, the mirror of open-collector.
    OpenEmitter = 11,
}
impl PinDirection {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "PIN_DIRECTION_UNSPECIFIED",
            Self::Input => "PIN_DIRECTION_INPUT",
            Self::Output => "PIN_DIRECTION_OUTPUT",
            Self::Inout => "PIN_DIRECTION_INOUT",
            Self::Passive => "PIN_DIRECTION_PASSIVE",
            Self::Power => "PIN_DIRECTION_POWER",
            Self::NoConnect => "PIN_DIRECTION_NO_CONNECT",
            Self::PowerIn => "PIN_DIRECTION_POWER_IN",
            Self::PowerOut => "PIN_DIRECTION_POWER_OUT",
            Self::Tristate => "PIN_DIRECTION_TRISTATE",
            Self::OpenCollector => "PIN_DIRECTION_OPEN_COLLECTOR",
            Self::OpenEmitter => "PIN_DIRECTION_OPEN_EMITTER",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "PIN_DIRECTION_UNSPECIFIED" => Some(Self::Unspecified),
            "PIN_DIRECTION_INPUT" => Some(Self::Input),
            "PIN_DIRECTION_OUTPUT" => Some(Self::Output),
            "PIN_DIRECTION_INOUT" => Some(Self::Inout),
            "PIN_DIRECTION_PASSIVE" => Some(Self::Passive),
            "PIN_DIRECTION_POWER" => Some(Self::Power),
            "PIN_DIRECTION_NO_CONNECT" => Some(Self::NoConnect),
            "PIN_DIRECTION_POWER_IN" => Some(Self::PowerIn),
            "PIN_DIRECTION_POWER_OUT" => Some(Self::PowerOut),
            "PIN_DIRECTION_TRISTATE" => Some(Self::Tristate),
            "PIN_DIRECTION_OPEN_COLLECTOR" => Some(Self::OpenCollector),
            "PIN_DIRECTION_OPEN_EMITTER" => Some(Self::OpenEmitter),
            _ => None,
        }
    }
}
